import React, { useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/UserPages.css";

const CreateRentalListing = () => {
  const [form, setForm] = useState({
    title: "",
    description: "",
    price: "",
    duration: "",
    image: ""
  });

  const sellerId = sessionStorage.getItem("userId");

  const handleSubmit = async (e) => {
    e.preventDefault();
    await fetch(`${API_BASE_URL}/api/rentals`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ...form, seller_id: sellerId }),
    });
    alert("Rental listing created!");
    setForm({ title: "", description: "", price: "", duration: "", image: "" });
  };

  return (
    <>
      <Navbar />
      <div className="page-container">
        <div className="page-header">
          <h2>Post Rental Equipment</h2>
        </div>
        <div className="card">
          <form onSubmit={handleSubmit} className="form">
            <input placeholder="Title" value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} required />
            <textarea placeholder="Description" value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} required />
            <input type="number" placeholder="Price" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value })} required />
            <input placeholder="Duration (e.g. 1 Week)" value={form.duration} onChange={(e) => setForm({ ...form, duration: e.target.value })} required />
            <input placeholder="Image URL" value={form.image} onChange={(e) => setForm({ ...form, image: e.target.value })} />
            <button type="submit" className="primary-btn">Post Rental</button>
          </form>
        </div>
      </div>
      <Footer />
    </>
  );
};

export default CreateRentalListing;
